-- CAREERS: job openings managed in Admin -> Admin / Finance -> Career jobs.
-- The Careers page shows open jobs from this table (until this is run it uses src/lib/jobs.ts).
-- Run once in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: existing jobs are kept.

create table if not exists jobs (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null check (char_length(slug) <= 120),
  title text not null check (char_length(title) <= 160),
  department text not null default '',
  location text not null default 'Johor Bahru, Johor',
  type text not null default 'Full-time',
  teaser text not null default '',
  summary text not null default '',
  responsibilities jsonb not null default '[]'::jsonb,
  requirements jsonb not null default '[]'::jsonb,
  offer jsonb not null default '[]'::jsonb,
  sort_order int not null default 0,
  is_open boolean not null default true,
  created_at timestamptz not null default now()
);

alter table jobs enable row level security;
drop policy if exists "public read open jobs" on jobs;
create policy "public read open jobs" on jobs for select using (is_open or is_admin());
drop policy if exists "admin all jobs" on jobs;
create policy "admin all jobs" on jobs for all using (is_admin()) with check (is_admin());

-- The current openings (from src/lib/jobs.ts)
insert into jobs (slug, title, department, location, type, teaser, summary, responsibilities, requirements, offer, sort_order)
values
  ('sales-executive', 'Sales Executive', 'Sales', 'Johor Bahru, Johor', 'Full-time', 'Grow our customer base across labs, schools and industry.', 'You will be the first point of contact for customers who need laboratory instruments, consumables and chemicals. You find new customers, understand what their lab needs, and turn that into quotations and orders.', '["Find and follow up new customers in universities, schools, industry and testing labs.","Prepare quotations and follow them up until the order is confirmed.","Visit customers, understand their needs and recommend suitable products and brands.","Work with the store, operations and service teams so orders are delivered on time.","Keep customer records and sales reports up to date."]'::jsonb, '["Diploma or degree in Science, Chemistry, Business or a related field.","Experience in laboratory or scientific supply sales is an advantage; fresh graduates are welcome to apply.","Good communication skills in English and Bahasa Malaysia. Mandarin is an advantage.","Comfortable with MS Office and willing to travel within Johor and nearby states.","Own transport and a valid driving licence."]'::jsonb, '["Basic salary with sales commission, based on experience.","Product training on the brands we carry.","EPF and SOCSO contributions.","Clear room to grow into senior sales roles."]'::jsonb, 10),
  ('account-executive', 'Account Executive', 'Finance & Accounts', 'Johor Bahru, Johor', 'Full-time', 'Keep invoices, payments and company accounts accurate.', 'You will look after the day-to-day accounts of the company: customer invoices, supplier bills, payments and month-end records, so that our books are always accurate and up to date.', '["Prepare invoices, credit notes and statements for customers.","Record supplier bills and process payments on time.","Follow up outstanding customer payments.","Reconcile bank and supplier accounts each month.","Support the monthly closing, audit and tax submissions."]'::jsonb, '["Diploma or degree in Accounting, Finance or a related field.","At least 1 year of accounting experience is preferred.","Working knowledge of an accounting software and MS Excel.","Careful, organised and able to meet deadlines.","Good English and Bahasa Malaysia."]'::jsonb, '["Fixed monthly salary, based on experience.","EPF and SOCSO contributions.","Training and support from a friendly accounts team.","Stable, regular Monday to Friday working hours."]'::jsonb, 20),
  ('operation-executive', 'Operation Executive', 'Operations', 'Johor Bahru, Johor', 'Full-time', 'Make sure every order is processed and delivered on time.', 'You will coordinate the work between sales, the store and our suppliers so that orders are ordered, received and delivered correctly and on time. You keep the process moving and solve problems before customers notice them.', '["Process confirmed sales orders and place purchase orders with suppliers.","Track shipments and update the sales team and customers on delivery dates.","Arrange import documents and local delivery with forwarders and couriers.","Keep stock and order records accurate.","Handle order issues, returns and delays with suppliers and customers."]'::jsonb, '["Diploma or degree in Business, Logistics, Supply Chain or a related field.","Experience in purchasing, logistics or order processing is an advantage.","Good with details and able to handle several orders at once.","Good communication skills and comfortable with MS Office.","Able to work with different teams."]'::jsonb, '["Fixed monthly salary, based on experience.","EPF and SOCSO contributions.","Hands-on learning about scientific products and imports.","Opportunity to grow into a senior operations role."]'::jsonb, 30),
  ('store-assistant', 'Store Assistant', 'Store & Warehouse', 'Johor Bahru, Johor', 'Full-time', 'Receive, pack and keep our laboratory stock in order.', 'You will keep our store organised and make sure the right products are received, stored, packed and ready for delivery. Care with handling is important, as many of our products are glassware, chemicals and instruments.', '["Receive and check incoming goods against delivery orders.","Store products safely and keep the store neat and labelled.","Pick, pack and prepare orders for delivery or customer collection.","Do regular stock checks and report differences.","Follow safe handling rules for chemicals and fragile items."]'::jsonb, '["SPM or above.","Experience in a store or warehouse is an advantage.","Able to lift and move stock safely.","Honest, careful and willing to learn.","Valid driving licence is an advantage."]'::jsonb, '["Fixed monthly salary.","EPF and SOCSO contributions.","Training on safe handling of laboratory products.","Stable, regular working hours."]'::jsonb, 40),
  ('service-engineer', 'Service Engineer', 'Technical Service', 'Johor Bahru, Johor', 'Full-time', 'Install, calibrate and repair laboratory equipment.', 'You will install, maintain, calibrate and repair laboratory instruments at customer sites and in our workshop, so that our customers'' equipment keeps running accurately.', '["Install equipment and train customers to use it.","Carry out calibration and preventive maintenance.","Diagnose faults and repair instruments on site or in the workshop.","Record every service job and report back to the service team.","Give technical support to customers and to the sales team."]'::jsonb, '["Diploma or degree in Electrical, Electronics, Mechanical, Mechatronics or a related field.","Experience with laboratory or electronic equipment is an advantage.","Able to read technical manuals and troubleshoot step by step.","Willing to travel to customer sites.","Own transport and a valid driving licence."]'::jsonb, '["Fixed monthly salary with allowances for site work.","Product and service training.","EPF and SOCSO contributions.","Opportunity to grow as a technical specialist."]'::jsonb, 50),
  ('admin-customer-service', 'Admin Customer Service', 'Customer Service', 'Johor Bahru, Johor', 'Full-time', 'Be the friendly voice and inbox customers reach first.', 'You will answer customer calls, emails and WhatsApp messages, prepare quotations with the sales team and keep our admin work running smoothly. You are the first person many customers speak to.', '["Reply to customer enquiries by phone, email and WhatsApp.","Prepare quotations and documents for the sales team.","Keep customer and order records up to date.","Follow up with customers on quotations, deliveries and service jobs.","Support the team with general office administration."]'::jsonb, '["SPM, Diploma or degree in any field.","Good communication skills in English and Bahasa Malaysia. Mandarin is an advantage.","Comfortable with MS Office and typing.","Polite, patient and organised.","Fresh graduates are welcome to apply."]'::jsonb, '["Fixed monthly salary, based on experience.","EPF and SOCSO contributions.","On-the-job training about our products and services.","Stable, regular Monday to Friday working hours."]'::jsonb, 60)
on conflict (slug) do nothing;

select title, is_open from jobs order by sort_order;
